ACK={'Q30':'f59c9181eb5a6371d93cf648ff15aa771f4af6de04bd9121c9bf2090fb2731f4','DEEPSEEK':'fe4768a91606bbbf89f1b28a897f0a6648fb8e83d3d621093313e03743ec1acf','OLMOE':'9c4d08a960f53acece00dbb3143cba460c22bc638ff4a879833c0e4460b98e39'}
def load(p):return json.loads(Path(p).read_text())
def sha(p):
 h=hashlib.sha256();h.update(Path(p).read_bytes());return h.hexdigest()
