def main():
 a=argparse.ArgumentParser();a.add_argument('--authority',type=Path,required=True);a.add_argument('--out',type=Path,required=True);x=a.parse_args();o=x.out;o.mkdir(parents=True,exist_ok=True)
 r={k:load(o/(k+'_RECOMPUTE.json')) for k in RUN}
 audit={}
 for k,run in RUN.items():
  root=x.authority/'raw'/run; catalog=x.authority/'catalog'/'entries'/(run+'.json'); ack=x.authority/'reports'/'transfer_acks'/(run+'.TRANSFER_ACK.json')
  audit[k]={'run_id':run,'raw_exists':root.is_dir(),'manifest_sha256':sha(root/'RUN_MANIFEST.json'),'catalog_exists':catalog.is_file(),'catalog_sha256':sha(catalog) if catalog.is_file() else None,'catalog_expected':CAT[k],'catalog_matches_expected':catalog.is_file() and sha(catalog)==CAT[k],'ack_exists':ack.is_file(),'ack_sha256':sha(ack) if ack.is_file() else None,'ack_expected':ACK[k],'ack_matches_expected':ack.is_file() and sha(ack)==ACK[k]}
 dump(o/'AUTHORITY_AUDIT.json',{'status':'PASS' if all(v['raw_exists'] and v['catalog_matches_expected'] and v['ack_matches_expected'] for v in audit.values()) else 'FAIL','lineages':audit,'node164_root':str(x.authority)})
