 dump(o/'HISTORICAL_REPRODUCTION_CHECK.json',{'status':'PASS' if all(q['equal'] for k in hist.values() for q in k.values()) else 'FAIL','comparisons':hist,'note':'historical values are post-recompute comparison references only'})
 composition={k:{'counts':v['role_event_counts'],'fractions':v['role_fractions'],'weight_input_fraction_delta':v['weight_input_fraction_delta'],'output_fraction':v['role_fractions']['OUTPUT'],'other_fraction':v['role_fractions']['OTHER']} for k,v in r.items()};dump(o/'OBJECT_COMPOSITION_COMPARISON.json',composition)
 static={k:{f:r[k][f] for f in ('selected_static_count','executed_static_count','proven_zero_static_count','failed_excluded_count','executed_fraction','dynamic_warp_records','active_lane_events')} for k in r};dump(o/'STATIC_EXECUTION_COMPARISON.json',static)
